// ESP32 — DC-Motor per MOSFET + PWM
#define MOTOR_PIN 25
#define PWM_CHANNEL 0
#define PWM_FREQ 1000
#define PWM_RESOLUTION 8

void setup() {
  Serial.begin(115200);
  ledcSetup(PWM_CHANNEL, PWM_FREQ, PWM_RESOLUTION);
  ledcAttachPin(MOTOR_PIN, PWM_CHANNEL);
}

void loop() {
  // Sanft hochfahren: 0 → 255 in ca. 3 Sekunden
  Serial.println("Motor läuft hoch ...");
  for (int duty = 0; duty <= 255; duty++) {
    ledcWrite(PWM_CHANNEL, duty);
    delay(12);
  }

  // Vollgas halten: 2 Sekunden
  Serial.println("Vollgas!");
  delay(2000);

  // Sanft bremsen: 255 → 0 in ca. 3 Sekunden
  Serial.println("Motor bremst ...");
  for (int duty = 255; duty >= 0; duty--) {
    ledcWrite(PWM_CHANNEL, duty);
    delay(12);
  }

  // Pause: 2 Sekunden
  Serial.println("Stop.");
  delay(2000);
}
